                if new_grid[r][c] == 6: new_grid[r][c] = 0
                elif new_grid[r][c] == 0: new_grid[r][c] = 6
        elif r == 7:
            # Flip columns 1, 10
            for c in [1, 10]:
                if new_grid[r][c] == 6: new_grid[r][c] = 0
                elif new_grid[r][c] == 0: new_grid[r][c] = 6
        elif r == 9:
            # Flip columns 1, 4, 7, 10
            for c in [1, 4, 7, 10]:
                if new_grid[r][c] == 6: new_grid[r][c] = 0
                elif new_grid[r][c] == 0: new_grid[r][c] = 6
        elif r == 11:
            # Flip columns 7, 13
            for c in [7, 13]:
                if new_grid[r][c] == 6: new_grid[r][c] = 0
                elif new_grid[r][c] == 0: new_grid[r][c] = 6
        # Other rows unchanged

